109	// `changed` lists the keys whose value differs from the saved preset; only
110	// read when the query asks for changed settings.
111	inline SettingsSearchResult search_setting_definitions(const std::vector<SettingDefinition>& definitions,
112	                                                       const SettingsQuery& query,
113	                                                       const std::vector<std::string>& changed = {})
114	{
115	    SettingsSearchResult result;
116	    std::size_t offset = 0;
117	    if (query.limit == 0 || query.limit > 25) {
118	        result.error = SettingIssue{"", "invalid_arguments", "Search limit must be between 1 and 25."};
119	        return result;
120	    }
121	    if (!query.cursor.empty()) {
122	        const std::string_view cursor(query.cursor);
123	        const auto digits = cursor.substr(std::min<std::size_t>(7, cursor.size()));
124	        const auto parsed = std::from_chars(digits.data(), digits.data() + digits.size(), offset);
125	        if (cursor.substr(0, 7) != "offset:" || digits.empty() || parsed.ec != std::errc() ||
126	            parsed.ptr != digits.data() + digits.size()) {
127	            result.error = SettingIssue{"", "invalid_arguments", "Invalid settings cursor. Search again without a cursor."};
128	            return result;
129	        }
130	    }
131	    // Several words or keys search for each of them; a setting that matches
132	    // more of them ranks first, then by how well its best term matched.
133	    std::vector<std::string> terms;
134	    const std::string text = ascii_lower(query.text);
135	    for (std::size_t start = 0; start <= text.size();) {
136	        const std::size_t end = std::min(text.find_first_of(" ,;", start), text.size());
137	        if (end > start)
138	            terms.push_back(text.substr(start, end - start));
139	        start = end + 1;
140	    }
141	    if (terms.empty())
142	        terms.push_back({});
143	    std::vector<std::pair<std::size_t, const SettingDefinition*>> matches;
144	    for (const auto& def : definitions) {
145	        if (query.writable_only && !def.writable)
146	            continue;
147	        if (query.changed_only && std::find(changed.begin(), changed.end(), def.key) == changed.end())
148	            continue;
149	        const std::string key = ascii_lower(def.key), label = ascii_lower(def.label), description = ascii_lower(def.description);
150	        std::size_t matched = 0, best = 4;
151	        for (const std::string& term : terms) {
152	            // A key that holds the term ranks with the keys that start with it:
153	            // "support" finds enable_support among the support_ keys.
154	            const std::size_t rank = key == term ? 0 : key.find(term) != std::string::npos ? 1 : label.find(term) != std::string::npos ? 2 :
155	                                     description.find(term) != std::string::npos ? 3 : 4;
156	            if (rank < 4) {
157	                ++matched;
158	                best = std::min(best, rank);
159	            }
160	        }
161	        if (matched > 0)
162	            matches.emplace_back((terms.size() - matched) * 4 + best, &def);
163	    }
164	    std::sort(matches.begin(), matches.end(), [](const auto& a, const auto& b) {
165	        return a.first < b.first || (a.first == b.first && a.second->key < b.second->key);
166	    });
167	    if (offset > matches.size()) {
168	        result.error = SettingIssue{"", "invalid_arguments", "Settings cursor is past the last match. Search again."};
169	        return result;
170	    }
171	    const std::size_t end = offset + std::min(query.limit, matches.size() - offset);
172	    for (std::size_t i = offset; i < end; ++i)
173	        result.items.push_back(*matches[i].second);
174	    result.truncated = end < matches.size();
175	    if (result.truncated)
176	        result.next_cursor = "offset:" + std::to_string(end);
177	    return result;
178	}
