33	// Orca's scalar deserializers accept a numeric prefix (e.g. "4bad"). Check
34	// complete consumption before calling the authoritative parser, so malformed
35	// input cannot silently become a different previewed value.
36	inline bool complete_setting_number(const std::string& text, ConfigOptionType type)
37	{
38	    if (type != coFloat && type != coInt && type != coPercent) return true;
39	    std::istringstream input(text);
40	    input.imbue(std::locale::classic());
41	    double number;
42	    if (!(input >> number) || !std::isfinite(number)) return false;
43	    input >> std::ws;
44	    if (type == coPercent && input.peek() == '%') { input.get(); input >> std::ws; }
45	    if (!input.eof()) return false;
46	    if (type == coInt) {
47	        std::istringstream integer_input(text);
48	        int integer;
49	        if (!(integer_input >> integer)) return false;
50	        integer_input >> std::ws;
51	        return integer_input.eof();
52	    }
53	    return true;
54	}
