56	// Parses one value into `config` the way a patch does, with the setting's
57	// own bounds; the result says why a value was refused.
58	inline std::optional<std::string> set_setting_value(DynamicPrintConfig& config, const std::string& key, const std::string& text)
59	{
60	    const ConfigOptionDef* definition = print_config_def.get(key);
61	    // A list holds one value per extruder, or per filament and nozzle kind,
62	    // and a patch keeps that shape: a shorter list would drop the rest.
63	    if ((definition->type & coVectorType) != 0) {
64	        const auto* before = dynamic_cast<const ConfigOptionVectorBase*>(config.option(key));
65	        const std::size_t count = before != nullptr ? before->size() : 1;
66	        try {
67	            config.set_deserialize_strict(key, text);
68	        } catch (const BadOptionValueException& error) {
69	            return std::string(error.what());
70	        }
71	        const auto* after = static_cast<const ConfigOptionVectorBase*>(config.option(key));
72	        if (after->size() != count)
73	            return "This setting holds " + std::to_string(count) + " values; give " + std::to_string(count) +
74	                   ", separated by commas.";
75	        const ConfigOptionType element = ConfigOptionType(definition->type & ~coVectorType);
76	        if (element == coInt || element == coFloat || element == coPercent)
77	            for (std::size_t index = 0; index < after->size(); ++index) {
78	                if (after->is_nil(index))
79	                    continue;
80	                double value;
81	                if (const auto* ints = dynamic_cast<const ConfigOptionInts*>(after)) value = ints->get_at(index);
82	                else if (const auto* nullable_ints = dynamic_cast<const ConfigOptionIntsNullable*>(after)) value = nullable_ints->get_at(index);
83	                else if (const auto* floats = dynamic_cast<const ConfigOptionFloats*>(after)) value = floats->get_at(index);
84	                else value = dynamic_cast<const ConfigOptionFloatsNullable&>(*after).get_at(index);
85	                if (!std::isfinite(value) || !definition->is_value_valid(value))
86	                    return std::string("A value is outside the setting's bounds.");
87	            }
88	        return std::nullopt;
89	    }
90	    if (!complete_setting_number(text, definition->type))
91	        return "Expected a complete finite " + setting_type(definition->type) + " value.";
92	    try {
93	        config.set_deserialize_strict(key, text);
94	    } catch (const BadOptionValueException& error) {
95	        return std::string(error.what());
96	    }
97	    const ConfigOption* option = config.option(key);
98	    // Bounds by type: a boolean has none, and reading one as a float is
99	    // undefined behaviour.
100	    if (definition->type == coEnum)
101	        return definition->has_enum_value(option->serialize()) ? std::nullopt : std::optional<std::string>("Value is not in the allowed enum values.");
102	    const bool numeric = definition->type == coInt || definition->type == coFloat || definition->type == coPercent ||
103	                         definition->type == coFloatOrPercent;
104	    if (numeric && !definition->is_value_valid(definition->type == coInt ? static_cast<double>(config.opt_int(key)) :
105	                                                                           static_cast<const ConfigOptionFloat*>(option)->value))
106	        return std::string("Value is outside the setting's bounds.");
107	    return std::nullopt;
108	}
