110	// Audit against ConfigManipulation::update_print_fff_config. These are every
111	// active modal predicate, including unrelated pre-existing invalid values:
112	// update() evaluates the entire config after any allowed batch. Keep refusal
113	// here; the live normalizer remains unchanged and owns its UI behavior.
114	inline void check_process_dialogs(const DynamicPrintConfig& config, SettingsPreview& result)
115	{
116	    const auto block = [&](bool condition, const std::string& key, const std::string& message) {
117	        if (condition) result.issues.push_back({key, "incompatible_settings", message});
118	    };
119	    const double height = config.opt_float("layer_height");
120	    const auto& printer = wxGetApp().preset_bundle->printers.get_edited_preset().config;
121	    const double maximum = printer.opt_float("max_layer_height", 0);
122	    if (height < EPSILON)
123	        result.issues.push_back({"layer_height", "invalid_setting_value", "Layer height is below Orca's minimum.", {}, {}, EPSILON, {}});
124	    if (maximum > 0.2 && height > maximum + EPSILON)
125	        result.issues.push_back({"layer_height", "invalid_setting_value", "Layer height exceeds the printer maximum.", {}, {}, {}, maximum});
126	    for (const auto* key : {"ironing_spacing", "support_ironing_spacing"})
127	        block(config.opt_float(key) < 0.05, key, "Ironing spacing would open Orca's correction dialog; correct it first.");
128	    block(config.opt_float("initial_layer_print_height") < EPSILON, "initial_layer_print_height", "Initial layer height would open Orca's correction dialog.");
129	    for (const auto* key : {"xy_hole_compensation", "xy_contour_compensation"})
130	        block(std::abs(config.opt_float(key)) > 2, key, "XY compensation would open Orca's correction dialog.");
131	    block(config.opt_float("elefant_foot_compensation") > 1, "elefant_foot_compensation", "Elephant foot compensation would open Orca's correction dialog.");
132	    block(config.opt_bool("spiral_mode") && !(config.opt_int("wall_loops") == 1 && config.opt_int("top_shell_layers") == 0 &&
133	        config.option<ConfigOptionPercent>("sparse_infill_density")->value == 0 && !config.opt_bool("enable_support") &&
134	        config.opt_int("enforce_support_layers") == 0 && !config.opt_bool("detect_thin_wall") && !config.opt_bool("overhang_reverse") &&
135	        config.opt_enum<TimelapseType>("timelapse_type") == tlTraditional && !config.opt_bool("enable_wrapping_detection")),
136	        "spiral_mode", "Spiral mode conflicts with wall_loops, top_shell_layers, infill, support, thin walls, overhang reversal, timelapse, or wrapping detection.");
137	    block(config.opt_bool("alternate_extra_wall") && config.opt_enum<EnsureVerticalShellThickness>("ensure_vertical_shell_thickness") == evstAll,
138	        "alternate_extra_wall", "Alternate extra wall conflicts with ensure_vertical_shell_thickness=all.");
139	    block(config.opt_enum<SeamScarfType>("seam_slope_type") != SeamScarfType::None && config.get_abs_value("seam_slope_start_height") >= height,
140	        "layer_height", "Layer height conflicts with seam_slope_type and seam_slope_start_height; scarf start height must be below layer height.");
141	    block(config.opt_float("infill_lock_depth") > config.opt_float("skin_infill_depth"), "infill_lock_depth", "Infill lock depth exceeds skin_infill_depth.");
142	    block(config.opt_enum<FuzzySkinMode>("fuzzy_skin_mode") != FuzzySkinMode::Displacement &&
143	        config.opt_enum<PerimeterGeneratorType>("wall_generator") != PerimeterGeneratorType::Arachne,
144	        "fuzzy_skin_mode", "This fuzzy skin mode requires wall_generator=arachne.");
145	}
