147	// ConfigManipulation resets support_style to default, silently, when it does
148	// not fit the support type. A patch that would be rewritten that way is
149	// refused with the styles that fit, rather than accepted and then changed.
150	inline void check_support_style(const DynamicPrintConfig& config, const std::map<std::string, std::string>& patch,
151	                                SettingsPreview& result)
152	{
153	    if (!config.opt_bool("enable_support") ||
154	        (!patch.count("support_style") && !patch.count("support_type") && !patch.count("enable_support")))
155	        return;
156	    const bool tree = is_tree(config.opt_enum<SupportType>("support_type"));
157	    const std::vector<SupportMaterialStyle> fitting = tree ?
158	        std::vector<SupportMaterialStyle>{smsDefault, smsTreeSlim, smsTreeStrong, smsTreeHybrid, smsTreeOrganic} :
159	        std::vector<SupportMaterialStyle>{smsDefault, smsGrid, smsSnug};
160	    const auto style = config.opt_enum<SupportMaterialStyle>("support_style");
161	    if (std::find(fitting.begin(), fitting.end(), style) != fitting.end())
162	        return;
163	    std::vector<std::string> allowed;
164	    for (SupportMaterialStyle candidate : fitting)
165	        allowed.push_back(ConfigOptionEnum<SupportMaterialStyle>(candidate).serialize());
166	    result.issues.push_back({"support_style", "invalid_setting_value",
167	                             std::string("With ") + (tree ? "tree" : "normal") +
168	                                 " supports, support_style must be one of the allowed values; OrcaSlicer would reset it to default.",
169	                             allowed});
170	}
