186	inline void predict_process_normalization(DynamicPrintConfig& config)
187	{
188	    // The modal predicates above were checked first. Execute Orca's own
189	    // normalization on the clone with no presentation callbacks; don't keep
190	    // a duplicate table of dependent values or infill-pattern capabilities.
191	    ConfigManipulation normalizer([] {}, [](const std::string&, bool, int) {}, {}, {});
192	    auto& bundle = *wxGetApp().preset_bundle;
193	    const auto& selected = bundle.prints.get_selected_preset();
194	    normalizer.initialize_support_material_overhangs_queried(!selected.is_system && !selected.is_dirty &&
195	        config.opt_bool("enable_support") && !config.opt_bool("detect_overhang_wall"));
196	    normalizer.set_is_BBL_Printer(bundle.is_bbl_vendor());
197	    normalizer.update_print_fff_config(&config, true, false);
