55	    // The values a target prints with: the process values, then the object's
56	    // own overrides.
57	    std::map<std::string, std::string> effective(const SettingsTarget& target) const
58	    {
59	        auto result = values;
60	        if (target.object)
61	            if (const auto found = overrides.find(target.object->value()); found != overrides.end())
62	                for (const auto& [key, value] : found->second)
63	                    result[key] = value;
64	        return result;
65	    }
