72	    const FakePreset* preset(const SettingsTarget& target) const
73	    {
74	        const auto& all   = target.scope == SettingsScope::Filament ? filaments : printers;
75	        const auto  found = all.find(target.preset);
76	        return found == all.end() ? nullptr : &found->second;
77	    }
