89	    SettingsSearchResult search(const SettingsQuery& query, const std::vector<std::string>& process_changed) const
90	    {
91	        if (!preset_scope(query.target)) {
92	            auto result   = search_setting_definitions(definitions, query, process_changed);
93	            result.preset = "Fixture process";
94	            return result;
95	        }
96	        const FakePreset* found = preset(query.target);
97	        if (found == nullptr) {
98	            SettingsSearchResult result;
99	            result.error = unknown_preset(query.target);
100	            return result;
101	        }
102	        std::vector<std::string> changed;
103	        if (selected(query.target))
104	            for (const auto& [key, value] : found->values)
105	                if (found->saved.at(key) != value) changed.push_back(key);
106	        auto result   = search_setting_definitions(scope_definitions(query.target.scope), query, changed);
107	        result.preset = query.target.preset;
108	        return result;
109	    }
