111	    SettingsReadResult read(const std::vector<std::string>& keys, const SettingsTarget& target = {}) const
112	    {
113	        SettingsReadResult result;
114	        if (keys.empty() || keys.size() > 32) {
115	            result.error = SettingIssue{"", "invalid_arguments", "Read 1 to 32 setting keys."};
116	            return result;
117	        }
118	        if (preset_scope(target)) {
119	            const FakePreset* found = preset(target);
120	            if (found == nullptr) {
121	                result.error = unknown_preset(target);
122	                return result;
123	            }
124	            result.preset = target.preset;
125	            for (const auto& key : keys) {
126	                const auto* def = definition(key, target.scope);
127	                if (def == nullptr) {
128	                    result.unknown_keys.push_back(key);
129	                    result.issues.push_back(unknown(key, target.scope));
130	                    continue;
131	                }
132	                const auto& values = selected(target) ? found->values : found->saved;
133	                const bool  dirty  = selected(target) && found->values.at(key) != found->saved.at(key);
134	                result.items.push_back({key, values.at(key), dirty, false, *def});
135	            }
136	            return result;
137	        }
138	        result.preset = "Fixture process";
139	        for (const auto& key : keys) {
140	            const auto* def = definition(key);
141	            if (!def) {
142	                result.unknown_keys.push_back(key);
143	                result.issues.push_back(unknown(key));
144	            } else {
145	                const auto current = effective(target);
146	                const auto& value = current.at(key);
147	                const bool dirty = values.at(key) != preset_values.at(key);
148	                result.items.push_back({key, value, dirty, dirty, *def});
149	                if (target.object) {
150	                    const auto found = overrides.find(target.object->value());
151	                    result.items.back().overridden = found != overrides.end() && found->second.count(key) > 0;
152	                }
153	            }
154	        }
155	        return result;
156	    }
157	
158	    SettingsPreview preview(const SettingsPatch& patch) const
159	    {
160	        if (preset_scope(patch.target))
161	            return preview_preset(patch);
162	        SettingsPreview result;
163	        result.preset = "Fixture process";
164	        if (patch.changes.empty() || patch.changes.size() > 32) {
165	            result.issues.push_back({"", "invalid_arguments", "A patch must contain 1 to 32 settings."});
166	            return result;
167	        }
168	        const auto current = effective(patch.target);
169	        auto next = current;
170	        for (const auto& [key, text] : patch.changes) {
171	            const auto* def = definition(key);
172	            if (!def) {
173	                result.issues.push_back(unknown(key));
174	                continue;
175	            }
176	            if (!def->writable) {
177	                result.issues.push_back({key, "unsupported_setting_mutation", "This process setting is read-only."});
178	                continue;
179	            }
180	            if (patch.target.object && !object_setting(key)) {
181	                result.issues.push_back({key, "unsupported_scope", "This setting applies to the whole print and cannot differ per object."});
182	                continue;
183	            }
184	            std::string canonical = text;
185	            bool valid = true;
186	            if (def->type == "enum") {
187	                valid = std::find(def->enum_values.begin(), def->enum_values.end(), text) != def->enum_values.end();
188	            } else {
189	                std::string number = text;
190	                if (def->type == "percent" && !number.empty() && number.back() == '%')
191	                    number.pop_back();
192	                std::size_t consumed = 0;
193	                double value = 0;
194	                try {
195	                    value = std::stod(number, &consumed);
196	                    valid = consumed == number.size() && std::isfinite(value);
197	                } catch (const std::invalid_argument&) { valid = false; }
198	                  catch (const std::out_of_range&) { valid = false; }
199	                valid = valid && (!def->min || value >= *def->min) && (!def->max || value <= *def->max) &&
200	                        (def->type != "integer" || std::trunc(value) == value);
201	                if (valid && def->type == "integer") {
202	                    std::istringstream integer_input(number);
203	                    int integer;
204	                    valid = static_cast<bool>(integer_input >> integer);
205	                    integer_input >> std::ws;
206	                    valid = valid && integer_input.eof();
207	                }
208	                if (valid) {
209	                    std::ostringstream out;
210	                    out << std::setprecision(12) << value;
211	                    canonical = out.str() + (def->type == "percent" ? "%" : "");
212	                }
213	            }
214	            if (!valid) {
215	                result.issues.push_back({key, "invalid_setting_value", "Value is outside the setting's type or bounds.",
216	                                         def->enum_values, {}, def->min, def->max});
217	                continue;
218	            }
219	            next[key] = canonical;
220	        }
221	        if (next.at("spiral_mode") == "1" &&
222	            (next.at("wall_loops") != "1" || next.at("top_shell_layers") != "0" || next.at("sparse_infill_density") != "0%"))
223	            result.issues.push_back({"spiral_mode", "incompatible_settings", "Spiral mode requires one wall, no top layers, and no infill."});
224	
225	        // Active Orca normalization: with infill, line does not support multiline.
226	        // Support-gap rounding is compiled out in Orca; do not simulate a write
227	        // that the production owner does not perform.
228	        if (!patch.target.object && next.at("sparse_infill_density") != "0%" && next.at("sparse_infill_pattern") == "line" &&
229	            next.at("fill_multiline") != "1") {
230	            result.dependencies.push_back({"fill_multiline", current.at("fill_multiline"), "1"});
231	            result.warnings.push_back({"fill_multiline", "normalized_dependency", "Orca resets multiline infill to 1 for this pattern."});
232	        }
233	        for (const auto& [key, text] : patch.changes) {
234	            if (!definition(key) || !writable_setting(key))
235	                continue;
236	            if (next.at(key) != current.at(key))
237	                result.changes.push_back({key, current.at(key), next.at(key)});
238	            else
239	                result.warnings.push_back({key, "unchanged", "The setting already has this value."});
240	        }
241	        result.valid = result.issues.empty();
242	        return result;
243	    }
244	
245	    CommandResult apply(const SettingsPatch& patch, const std::vector<SettingChange>& expected, SettingsPreview& applied)
246	    {
247	        if (preset_scope(patch.target))
248	            return apply_preset(patch, expected, applied);
249	        applied = preview(patch);
250	        const auto current = effective(patch.target);
251	        for (const auto& change : expected)
252	            if (current.count(change.key) == 0 || current.at(change.key) != change.before)
253	                return CommandResult::failure(WorkspaceError::StaleSettings, "A previewed setting changed. Read and preview again.");
254	        if (!applied.valid)
255	            return CommandResult::failure(WorkspaceError::InvalidSettings, "The settings patch is invalid.");
256	        const auto actual = previewed_changes(applied);
257	        if (actual.size() != expected.size() || !std::equal(actual.begin(), actual.end(), expected.begin(),
258	            [](const auto& a, const auto& b) { return a.key == b.key && a.before == b.before && a.after == b.after; }))
259	            return CommandResult::failure(WorkspaceError::StaleSettings, "The patch no longer matches the preview.");
260	        if (actual.empty())
261	            return CommandResult::failure(WorkspaceError::NoChange, "All requested values are unchanged.");
262	        for (const auto& change : actual)
263	            (patch.target.object ? overrides[patch.target.object->value()] : values)[change.key] = change.after;
264	        for (const auto& change : applied.dependencies)
265	            applied.warnings.push_back({change.key, "normalized", "Orca normalized this dependent setting to " + change.after + "."});
266	        if (patch.persist_as) {
267	            preset_values    = values;
268	            applied.saved_as = *patch.persist_as;
269	        }
270	        applied.preset_dirty = values != preset_values;
271	        return CommandResult::success();
272	    }
273	
274	    std::vector<SettingDefinition> definitions, filament_definitions, printer_definitions;
275	    std::map<std::string, std::string> values, preset_values;
276	    std::map<std::uint64_t, std::map<std::string, std::string>> overrides;
277	    std::map<std::string, FakePreset> filaments, printers;
278	    std::string selected_filament{"Fixture PLA"}, selected_printer{"Fixture printer"};
279	    std::vector<std::string> filament_slots{"Fixture PLA", "Fixture PETG"};
280	
281	private:
282	    const std::vector<SettingDefinition>& scope_definitions(SettingsScope scope) const
283	    {
284	        return scope == SettingsScope::Filament ? filament_definitions : scope == SettingsScope::Printer ? printer_definitions : definitions;
285	    }
286	
287	    static SettingDefinition definition_of(std::string key, std::string type, std::string label, SettingsScope scope,
288	                                           std::optional<double> min = {}, std::optional<double> max = {}, std::string unit = {})
289	    {
290	        const bool writable = writable_setting(key, scope);
291	        return {std::move(key), std::move(type), label, scope_name(scope), label, std::move(unit), min, max, {}, {}, writable};
292	    }
293	
294	    static FakePreset preset_of(std::map<std::string, std::string> values, bool system) { return {values, values, system}; }
295	
296	    // What SettingsPreview says of a filament or printer patch, by the rules
297	    // the adapter applies: a preset not being edited changes only by being
298	    // saved, OrcaSlicer's own preset only into a copy, and a copy only of the
299	    // printer in use or of a filament in the project with no unsaved edits
300	    // lost on the way.
301	    SettingsPreview preview_preset(const SettingsPatch& patch) const
302	    {
303	        SettingsPreview result;
304	        const FakePreset* found = preset(patch.target);
305	        if (found == nullptr) {
306	            result.issues.push_back(unknown_preset(patch.target));
307	            return result;
308	        }
309	        result.preset = patch.target.preset;
310	        if (patch.changes.empty() || patch.changes.size() > 32) {
311	            result.issues.push_back({"", "invalid_arguments", "A patch must contain 1 to 32 settings."});
312	            return result;
313	        }
314	        const bool is_selected = selected(patch.target);
315	        const auto& current    = is_selected ? found->values : found->saved;
316	        auto next = current;
317	        for (const auto& [key, text] : patch.changes) {
318	            const auto* def = definition(key, patch.target.scope);
319	            if (def == nullptr) {
320	                result.issues.push_back(unknown(key, patch.target.scope));
321	                continue;
322	            }
323	            if (!def->writable) {
324	                result.issues.push_back({key, "unsupported_setting_mutation", std::string("This ") + scope_name(patch.target.scope) +
325	                                                                                  " setting is read-only."});
326	                continue;
327	            }
328	            if (def->type == "integer" &&
329	                (text.empty() || text.find_first_not_of("0123456789") != std::string::npos || std::stod(text) > *def->max)) {
330	                result.issues.push_back({key, "invalid_setting_value", "Value is outside the setting's type or bounds.", {}, {}, def->min, def->max});
331	                continue;
332	            }
333	            next[key] = text;
334	        }
335	        if (!result.issues.empty())
336	            return result;
337	        const auto& all = patch.target.scope == SettingsScope::Filament ? filaments : printers;
338	        if (!patch.persist_as) {
339	            if (!is_selected)
340	                result.issues.push_back({"", "not_selected", "\"" + patch.target.preset + "\" is not the preset being edited, so a "
341	                                                                                            "change to it is saved: pass persistAs."});
342	        } else if (*patch.persist_as == patch.target.preset) {
343	            if (found->system)
344	                result.issues.push_back({"", "read_only_preset", "\"" + patch.target.preset + "\" comes with OrcaSlicer and cannot be "
345	                                                                                                "overwritten. Save the change as a copy: "
346	                                                                                                "pass persistAs \"" + patch.target.preset + " - Copy\".",
347	                                         {}, {patch.target.preset + " - Copy"}});
348	        } else if (all.count(*patch.persist_as)) {
349	            result.issues.push_back({"", "name_taken", "Another preset is already named \"" + *patch.persist_as + "\".", {},
350	                                     {patch.target.preset + " - Copy (2)"}});
351	        }
352	        if (patch.persist_as && !is_selected) {
353	            if (patch.target.scope == SettingsScope::Printer && *patch.persist_as != patch.target.preset)
354	                result.issues.push_back({"", "not_selected", "A copy is saved only of the printer in use."});
355	            if (patch.target.scope == SettingsScope::Filament) {
356	                const FakePreset& editing = filaments.at(selected_filament);
357	                if (std::find(filament_slots.begin(), filament_slots.end(), patch.target.preset) == filament_slots.end())
358	                    result.issues.push_back({"", "not_in_project", "\"" + patch.target.preset + "\" is not one of the project's filaments."});
359	                else if (editing.values != editing.saved)
360	                    result.issues.push_back({"", "unsaved_edits", "The filament being edited has unsaved changes."});
361	            }
362	        }
363	        for (const auto& [key, text] : patch.changes) {
364	            if (next.at(key) != current.at(key))
365	                result.changes.push_back({key, current.at(key), next.at(key)});
366	            else
367	                result.warnings.push_back({key, "unchanged", "The setting already has this value."});
368	        }
369	        result.valid = result.issues.empty();
370	        return result;
371	    }
372	
373	    CommandResult apply_preset(const SettingsPatch& patch, const std::vector<SettingChange>& expected, SettingsPreview& applied)
374	    {
375	        applied = preview_preset(patch);
376	        if (const FakePreset* found = preset(patch.target)) {
377	            const auto& current = selected(patch.target) ? found->values : found->saved;
378	            for (const auto& change : expected)
379	                if (current.count(change.key) == 0 || current.at(change.key) != change.before)
380	                    return CommandResult::failure(WorkspaceError::StaleSettings, "A previewed setting changed. Read and preview again.");
381	        }
382	        if (!applied.valid)
383	            return CommandResult::failure(WorkspaceError::InvalidSettings, "The settings patch is invalid.");
384	        const auto actual = previewed_changes(applied);
385	        if (actual.size() != expected.size() || !std::equal(actual.begin(), actual.end(), expected.begin(),
386	            [](const auto& a, const auto& b) { return a.key == b.key && a.before == b.before && a.after == b.after; }))
387	            return CommandResult::failure(WorkspaceError::StaleSettings, "The patch no longer matches the preview.");
388	        if (actual.empty())
389	            return CommandResult::failure(WorkspaceError::NoChange, "All requested values are unchanged.");
390	        const bool   filament = patch.target.scope == SettingsScope::Filament;
391	        auto&        all      = filament ? filaments : printers;
392	        std::string& editing  = filament ? selected_filament : selected_printer;
393	        FakePreset&  target   = all.at(patch.target.preset);
394	        if (!selected(patch.target) && !filament) {
395	            // A printer not in use, saved in place.
396	            for (const auto& change : actual)
397	                target.values[change.key] = target.saved[change.key] = change.after;
398	            applied.saved_as = patch.target.preset;
399	            return CommandResult::success();
400	        }
401	        editing = patch.target.preset; // a filament in the project is opened in its tab first
402	        for (const auto& change : actual)
403	            target.values[change.key] = change.after;
404	        if (patch.persist_as) {
405	            if (*patch.persist_as == patch.target.preset) {
406	                target.saved = target.values;
407	            } else {
408	                // Save as: the copy holds the edits and takes the original's
409	                // place, which goes back to what it was saved as.
410	                all[*patch.persist_as] = {target.values, target.values, false};
411	                target.values          = target.saved;
412	                if (filament)
413	                    std::replace(filament_slots.begin(), filament_slots.end(), patch.target.preset, *patch.persist_as);
414	                editing = *patch.persist_as;
415	            }
416	            applied.saved_as = *patch.persist_as;
417	        }
418	        const FakePreset& now = all.at(editing);
419	        applied.preset_dirty  = now.values != now.saved;
420	        return CommandResult::success();
421	    }
422	
423	    void add(std::string key, std::string type, std::string label, std::string value,
424	             std::optional<double> min = {}, std::optional<double> max = {}, std::string unit = {})
425	    {
426	        values[key] = std::move(value);
427	        definitions.push_back({key, type, label, "Process", label, unit, min, max, {}, {}, writable_setting(key)});
428	    }
429	
430	    const SettingDefinition* definition(const std::string& key, SettingsScope scope = SettingsScope::Process) const
431	    {
432	        const auto& all   = scope_definitions(scope);
433	        const auto  found = std::find_if(all.begin(), all.end(), [&](const auto& def) { return def.key == key; });
434	        return found == all.end() ? nullptr : &*found;
435	    }
436	
437	    SettingIssue unknown(const std::string& key, SettingsScope scope = SettingsScope::Process) const
438	    {
439	        if (scope != SettingsScope::Printer && key == "nozzle_diameter")
440	            return {key, "unsupported_scope", std::string("This key is not a ") + scope_name(scope) + " setting."};
441	        return {key, "unknown_setting", "Unknown setting.", {}, setting_suggestions(key, scope_definitions(scope))};
442	    }
443	};
444	
445	} // namespace Slic3r::GUI::JusPrin::Workspace
